// stamp-verify-uat.test.mjs — UAT's ledger: production's signed history, then UAT's own lines (POS-1213).
//
// Wright, 2026-11-24 14:32:35Z (the CORE-176 split): UAT's gate verifies the copied prefix
// under the base public key through the trusted seal, and every later line under UAT's key
// ONLY; a handoff that cannot be used is red, never a skip; and with no handoff the verifier
// is production's, unchanged. Every key here is generated by the test (no deployment key).
//
//   node --test tools/stamp-verify-uat.test.mjs

import test from 'node:test';
import assert from 'node:assert/strict';
import { generateKeyPairSync } from 'node:crypto';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { execFileSync, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { parseStampLedger, sealChain, signSeal, appendSigned } from './stamp-mint.mjs';
import { verifyStampLedger, stampKeyPlan, handoffFromArgv } from './stamp-verify.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const VERIFY = join(HERE, 'stamp-verify.mjs');
const D = (date, id, from, to) => `- ${date} · ${id} · ${from} → ${to} · thread: new`;

function keypair(type = 'ed25519') {
  const { publicKey, privateKey } = generateKeyPairSync(type);
  return { pub: publicKey.export({ type: 'spki', format: 'pem' }), priv: privateKey.export({ type: 'pkcs8', format: 'pem' }) };
}

const LEDGER = (repo) => join(repo, 'WHITE_PAGES', 'stamp-ledger.md');
const entriesOf = (repo) => parseStampLedger(readFileSync(LEDGER(repo), 'utf8'));
const sealsOf = (repo) => sealChain(entriesOf(repo).map((e) => e.canonical));

function mintPass(repo, priv) {
  const keyFile = join(repo, 'mint-key.pem');
  writeFileSync(keyFile, priv);
  execFileSync(process.execPath, [join(HERE, 'stamp-mint.mjs'), '--append', '--key', keyFile, '--repo', repo], { encoding: 'utf8' });
  rmSync(keyFile);
}

function addMail(repo, ...lines) {
  const ml = join(repo, 'WHITE_PAGES', 'mail-ledger.md');
  writeFileSync(ml, readFileSync(ml, 'utf8') + lines.map((l) => `${l}\n`).join(''));
}

// Re-sign the entry at 0-based index i with `priv` (its seal, so only the key differs).
function resign(repo, i, priv) {
  const text = readFileSync(LEDGER(repo), 'utf8');
  const lines = text.split('\n');
  const at = lines.map((l, n) => (/^- .* · sig: [A-Za-z0-9_-]+$/.test(l) ? n : -1)).filter((n) => n !== -1);
  assert.equal(at.length, entriesOf(repo).length, 'every entry line found');
  lines[at[i]] = lines[at[i]].replace(/ · sig: [A-Za-z0-9_-]+$/, ` · sig: ${signSeal(sealsOf(repo)[i], priv)}`);
  writeFileSync(LEDGER(repo), lines.join('\n'));
}

// The UAT shape: a town whose ledger production signed (the copied prefix, `prefix` lines,
// its last seal the trusted one), then a crossing UAT's own pen minted with UAT's key.
function uatTown() {
  const prod = keypair(), uat = keypair();
  const repo = mkdtempSync(join(tmpdir(), 'stamp-uat-'));
  mkdirSync(join(repo, 'tools'), { recursive: true });
  mkdirSync(join(repo, 'WHITE_PAGES'), { recursive: true });
  writeFileSync(join(repo, 'tools', 'github-ids.json'), '{}');
  // the committed public anchor is production's, as on UAT's copied clone
  writeFileSync(join(repo, 'tools', 'stamp-pubkey.pem'), prod.pub);
  writeFileSync(join(repo, 'WHITE_PAGES', 'mail-ledger.md'), `# ledger\n\n${D('2026-06-12', 'a-1', 'alice', 'bob')}\n`);
  mintPass(repo, prod.priv);
  addMail(repo, D('2026-06-13', 'a-2', 'bob', 'carol'));
  mintPass(repo, prod.priv);
  const prefix = entriesOf(repo).length;
  const afterSeal = sealsOf(repo)[prefix - 1];
  addMail(repo, D('2026-06-14', 'u-1', 'carol', 'alice'), D('2026-06-14', 'u-2', 'alice', 'dave'));
  mintPass(repo, uat.priv);
  const total = entriesOf(repo).length;
  assert.ok(total > prefix + 1, `the UAT crossing minted more than one line (${prefix} then ${total})`);
  return { repo, prod, uat, prefix, total, afterSeal, handoff: { pubkeyPem: uat.pub, afterSeal } };
}

const cli = (repo, ...args) => spawnSync(process.execPath, [VERIFY, '--repo', repo, ...args], { encoding: 'utf8' });

test('POS-1213 · the handoff verifies production\'s copied prefix under its key and UAT\'s suffix under UAT\'s key', () => {
  const t = uatTown();
  try {
    const r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff });
    assert.equal(r.ok, true, r.problems.join('; '));
    assert.equal(r.lines, t.total);
    assert.ok(r.minted > 0);
    const note = r.notes.find((n) => n.startsWith('handoff: '));
    assert.match(note ?? '', new RegExp(`^handoff: lines 1–${t.prefix} verified under the base key \\(through the trusted seal\\), lines ${t.prefix + 1}–${t.total} under the handoff key sha256:[0-9a-f]{64} only$`));
    // the base key defaults to the clone's committed anchor, as the CLI reads it
    assert.equal(verifyStampLedger(t.repo, { handoff: t.handoff }).ok, true);
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · the production control: with no handoff, UAT\'s first line is refused in production\'s own words', () => {
  const t = uatTown();
  try {
    for (const opts of [{ pubkeyPem: t.prod.pub }, { pubkeyPem: t.prod.pub, handoff: null }, { pubkeyPem: t.prod.pub, handoff: undefined }, {}]) {
      const r = verifyStampLedger(t.repo, opts);
      assert.equal(r.ok, false);
      const sig = r.problems.filter((p) => p.includes('SIGNATURE'));
      assert.equal(sig.length, 1, r.problems.join('; '));
      assert.match(sig[0], new RegExp(`^line ${t.prefix + 1}: SIGNATURE FAILS — first divergence at "`), 'the crossing-331 refusal, word for word');
      assert.ok(!r.notes.some((n) => n.startsWith('handoff')), 'no handoff, no handoff note');
    }
    // and UAT's key alone (a whole-ledger swap) refuses the copied history at line 1
    const swapped = verifyStampLedger(t.repo, { pubkeyPem: t.uat.pub });
    assert.match(swapped.problems.find((p) => p.includes('SIGNATURE')) ?? '', /^line 1: SIGNATURE FAILS — /);
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · the production control at the CLI: no flags, production\'s green and production\'s red, unchanged', () => {
  const t = uatTown();
  try {
    const red = cli(t.repo);
    assert.equal(red.status, 1);
    assert.equal(red.stdout, '');
    assert.match(red.stderr, new RegExp(`^✗ stamp-ledger verification FAILED:\\n  - line ${t.prefix + 1}: SIGNATURE FAILS — first divergence at "`));
    assert.ok(!/handoff/.test(red.stderr));
    // a ledger production alone signed: the green line, and nothing else
    const prodOnly = uatTown();
    try {
      const text = readFileSync(LEDGER(prodOnly.repo), 'utf8').split('\n');
      const keep = text.filter((l) => !/^- /.test(l) || text.filter((x) => /^- /.test(x)).indexOf(l) < prodOnly.prefix);
      writeFileSync(LEDGER(prodOnly.repo), keep.join('\n'));
      const ml = join(prodOnly.repo, 'WHITE_PAGES', 'mail-ledger.md');
      writeFileSync(ml, readFileSync(ml, 'utf8').split('\n').filter((l) => !l.includes('· u-')).join('\n'));
      const green = cli(prodOnly.repo);
      assert.equal(green.status, 0, green.stderr);
      assert.match(green.stdout, new RegExp(`^✓ stamp-ledger verifies — ${prodOnly.prefix} line\\(s\\), \\d+ minted, chain \\+ signatures \\+ replay \\+ conservation \\+ lawful all green\\n$`));
      assert.equal(green.stderr, '');
    } finally { rmSync(prodOnly.repo, { recursive: true, force: true }); }
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · the CLI\'s two flags verify the mixed ledger, and come together or not at all', () => {
  const t = uatTown();
  try {
    const pemFile = join(t.repo, 'uat-pubkey.pem');
    writeFileSync(pemFile, t.uat.pub);
    const ok = cli(t.repo, '--handoff-pubkey', pemFile, '--handoff-after-seal', t.afterSeal);
    assert.equal(ok.status, 0, ok.stderr);
    assert.match(ok.stdout, new RegExp(`^✓ stamp-ledger verifies — ${t.total} line\\(s\\), `));
    assert.match(ok.stdout, new RegExp(`\\n  ! handoff: lines 1–${t.prefix} verified under the base key \\(through the trusted seal\\), lines ${t.prefix + 1}–${t.total} under the handoff key sha256:`));
    for (const [why, args] of [
      ['the key alone', ['--handoff-pubkey', pemFile]],
      ['the seal alone', ['--handoff-after-seal', t.afterSeal]],
      ['a flag twice', ['--handoff-pubkey', pemFile, '--handoff-after-seal', t.afterSeal, '--handoff-pubkey', pemFile]],
      ['a flag with no value', ['--handoff-after-seal', t.afterSeal, '--handoff-pubkey']],
      ['an unreadable key file', ['--handoff-pubkey', join(t.repo, 'no-such.pem'), '--handoff-after-seal', t.afterSeal]],
      ['a seal not of this ledger', ['--handoff-pubkey', pemFile, '--handoff-after-seal', 'f'.repeat(64)]],
    ]) {
      const r = cli(t.repo, ...args);
      assert.equal(r.status, 1, `${why}: ${r.stdout}`);
      assert.doesNotMatch(r.stdout, /✓/, `${why}: never green`);
      assert.match(r.stderr, /^✗ stamp-ledger verification FAILED:\n  - handoff: .* — signatures not verified\n/, `${why}: ${r.stderr}`);
    }
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · never either key: each side verifies under its own key only', () => {
  const t = uatTown();
  try {
    const sigRed = (r) => r.problems.find((p) => p.includes('SIGNATURE FAILS')) ?? r.problems.join('; ');
    // a UAT line signed by production's key is refused (production's key does not sign the suffix)
    resign(t.repo, t.prefix, t.prod.priv);
    let r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff });
    assert.equal(r.ok, false);
    assert.match(sigRed(r), new RegExp(`^line ${t.prefix + 1}: SIGNATURE FAILS under the handoff key, after line ${t.prefix} — `));
    resign(t.repo, t.prefix, t.uat.priv);
    assert.equal(verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff }).ok, true, 'restored');
    // a copied line re-signed by UAT's key is refused (UAT's key cannot re-sign production's history)
    resign(t.repo, 1, t.uat.priv);
    r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff });
    assert.match(sigRed(r), new RegExp(`^line 2: SIGNATURE FAILS under the base key, through line ${t.prefix} — `));
    // the whole ledger re-signed by UAT's key: the seals do not move, so the anchor still
    // names a seal, and the copied prefix is still refused under the base key
    for (let i = 0; i < t.total; i++) resign(t.repo, i, t.uat.priv);
    r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff });
    assert.match(sigRed(r), /^line 1: SIGNATURE FAILS under the base key/);
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · the trusted seal is where the handoff key starts, and only there', () => {
  const t = uatTown();
  try {
    // an anchor one line early hands a production line to UAT's key: refused there
    const early = sealsOf(t.repo)[t.prefix - 2];
    let r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: { pubkeyPem: t.uat.pub, afterSeal: early } });
    assert.match(r.problems.join('; '), new RegExp(`line ${t.prefix}: SIGNATURE FAILS under the handoff key, after line ${t.prefix - 1}`));
    // an anchor one line late asks production's key for UAT's first line: refused there
    const late = sealsOf(t.repo)[t.prefix];
    r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: { pubkeyPem: t.uat.pub, afterSeal: late } });
    assert.match(r.problems.join('; '), new RegExp(`line ${t.prefix + 1}: SIGNATURE FAILS under the base key, through line ${t.prefix + 1}`));
    // the anchor at the last line, before UAT has minted: green, and it says nothing came after
    const last = sealsOf(t.repo)[t.total - 1];
    for (let i = t.prefix; i < t.total; i++) resign(t.repo, i, t.prod.priv);
    r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: { pubkeyPem: t.uat.pub, afterSeal: last } });
    assert.equal(r.ok, true, r.problems.join('; '));
    assert.match(r.notes.join('\n'), new RegExp(`handoff: lines 1–${t.total} verified under the base key \\(through the trusted seal\\); no line after it yet`));
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · a handoff that cannot be used is red, never a skip', () => {
  const t = uatTown();
  try {
    const other = keypair(), x = keypair('x25519');
    for (const [why, handoff, said] of [
      ['the key missing', { afterSeal: t.afterSeal }, /the handoff is partial: no pubkeyPem/],
      ['the seal missing', { pubkeyPem: t.uat.pub }, /the handoff is partial: no afterSeal/],
      ['both missing', {}, /the handoff is partial: no afterSeal and no pubkeyPem/],
      ['not an object', 'uat', /the handoff is not \{ pubkeyPem, afterSeal \}/],
      ['an array', [t.uat.pub, t.afterSeal], /the handoff is not \{ pubkeyPem, afterSeal \}/],
      ['an extra field', { ...t.handoff, fromLine: 3 }, /the handoff names "fromLine": it takes pubkeyPem and afterSeal only/],
      ['a seal that is not hex', { pubkeyPem: t.uat.pub, afterSeal: 'line 40137' }, /afterSeal is not a seal \(64 lowercase hex\)/],
      ['an uppercase seal', { pubkeyPem: t.uat.pub, afterSeal: t.afterSeal.toUpperCase() }, /afterSeal is not a seal \(64 lowercase hex\)/],
      ['a seal not of this ledger', { pubkeyPem: t.uat.pub, afterSeal: '0'.repeat(64) }, /is not a seal of this ledger/],
      ['an empty key', { pubkeyPem: '', afterSeal: t.afterSeal }, /the handoff public key is empty/],
      ['a key that is not a key', { pubkeyPem: '-----BEGIN PUBLIC KEY-----\nnope\n-----END PUBLIC KEY-----\n', afterSeal: t.afterSeal }, /the handoff public key is not a readable public key/],
      ['a private key', { pubkeyPem: t.uat.priv, afterSeal: t.afterSeal }, /the handoff public key is a PRIVATE key/],
      ['a key not ed25519', { pubkeyPem: x.pub, afterSeal: t.afterSeal }, /the handoff public key is x25519, not ed25519/],
      ['the base key again', { pubkeyPem: t.prod.pub, afterSeal: t.afterSeal }, /the handoff public key is the base key/],
    ]) {
      const r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff });
      assert.equal(r.ok, false, `${why}: never green`);
      assert.ok(r.problems.some((p) => p.startsWith('handoff: ') && said.test(p) && p.endsWith(' — signatures not verified')), `${why}: ${r.problems.join('; ')}`);
      assert.ok(!r.problems.some((p) => p.includes('SIGNATURE FAILS')), `${why}: no signature was checked under an unusable handoff`);
      assert.ok(!r.notes.some((n) => n.startsWith('handoff: lines')), `${why}: no handoff green note`);
    }
    // a wrong UAT key (well-formed, not the one that signed): refused at UAT's first line
    const wrong = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: { pubkeyPem: other.pub, afterSeal: t.afterSeal } });
    assert.match(wrong.problems.join('; '), new RegExp(`line ${t.prefix + 1}: SIGNATURE FAILS under the handoff key`));
    // a bad base key under a handoff is a problem too, not a throw
    const badBase = verifyStampLedger(t.repo, { pubkeyPem: t.prod.priv, handoff: t.handoff });
    assert.match(badBase.problems.join('; '), /handoff: the base public key is a PRIVATE key/);
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · under the handoff every other check still runs: chain, replay, conservation', () => {
  const t = uatTown();
  try {
    // an edited suffix line (its text changed, its old signature kept): the seal moves, so it fails
    const p = LEDGER(t.repo);
    const text = readFileSync(p, 'utf8');
    const lines = text.split('\n');
    const at = lines.map((l, n) => (/^- .* · sig: /.test(l) ? n : -1)).filter((n) => n !== -1);
    const edited = lines.slice();
    edited[at[t.prefix]] = edited[at[t.prefix]].replace(/MINT → (\S+)/, 'MINT → mallory');
    assert.notEqual(edited[at[t.prefix]], lines[at[t.prefix]], 'the edit took');
    writeFileSync(p, edited.join('\n'));
    let r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff });
    assert.equal(r.ok, false);
    assert.match(r.problems.join('; '), new RegExp(`line ${t.prefix + 1}: SIGNATURE FAILS under the handoff key`));
    writeFileSync(p, text);
    // a mint UAT's key signs perfectly but the mail never earned: the replay refuses it
    const last = entriesOf(t.repo).at(-1).canonical;
    appendSigned(t.repo, [last], t.uat.priv);
    r = verifyStampLedger(t.repo, { pubkeyPem: t.prod.pub, handoff: t.handoff });
    assert.equal(r.ok, false);
    assert.ok(!r.problems.some((x) => x.includes('SIGNATURE')), `signed well: ${r.problems.join('; ')}`);
    assert.ok(r.problems.some((x) => x.startsWith(`line ${t.total + 1}: ledger mint beyond the derivation`)), `the replay names the forged line: ${r.problems.join('; ')}`);
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · stampKeyPlan, the one rule for callers that check line by line', () => {
  const t = uatTown();
  try {
    const seals = sealsOf(t.repo);
    const prodKey = verifyKeyId(t.prod.pub), uatKey = verifyKeyId(t.uat.pub);
    const plan = stampKeyPlan(seals, t.prod.pub, t.handoff);
    assert.deepEqual(plan.problems, []);
    assert.equal(plan.anchor, t.prefix);
    assert.equal(keyId(plan.keyAt(0)), prodKey);
    assert.equal(keyId(plan.keyAt(t.prefix - 1)), prodKey, 'the anchor line itself is the base key\'s');
    assert.equal(keyId(plan.keyAt(t.prefix)), uatKey, 'the first line after it is the handoff key\'s');
    assert.equal(keyId(plan.keyAt(t.total - 1)), uatKey);
    const none = stampKeyPlan(seals, t.prod.pub, null);
    assert.equal(none.anchor, 0);
    assert.equal(keyId(none.keyAt(t.total - 1)), prodKey, 'no handoff: the base key for every line');
    const bad = stampKeyPlan(seals, t.prod.pub, { pubkeyPem: t.uat.pub });
    assert.equal(bad.keyAt, null);
    assert.match(bad.problems.join('; '), /partial/);
  } finally { rmSync(t.repo, { recursive: true, force: true }); }
});

test('POS-1213 · handoffFromArgv: null without the flags, the pair with them, a throw for anything else', () => {
  const dir = mkdtempSync(join(tmpdir(), 'stamp-uat-argv-'));
  try {
    const pem = join(dir, 'k.pem');
    writeFileSync(pem, 'PEM');
    assert.equal(handoffFromArgv(['node', 'stamp-verify.mjs', '--repo', dir]), null);
    assert.deepEqual(handoffFromArgv(['node', 'v', '--handoff-after-seal', 'abc', '--handoff-pubkey', pem]), { pubkeyPem: 'PEM', afterSeal: 'abc' });
    assert.throws(() => handoffFromArgv(['node', 'v', '--handoff-pubkey', pem]), /come together or not at all/);
    assert.throws(() => handoffFromArgv(['node', 'v', '--handoff-pubkey', '--handoff-after-seal', 'abc']), /--handoff-pubkey has no value/);
    assert.throws(() => handoffFromArgv(['node', 'v', '--handoff-pubkey', join(dir, 'missing'), '--handoff-after-seal', 'abc']), /cannot be read \(ENOENT\)/);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

function keyId(keyObject) { return keyObject.export({ type: 'spki', format: 'der' }).toString('base64'); }
function verifyKeyId(pem) { return Buffer.from(pem.replace(/-----[^-]+-----|\s/g, ''), 'base64').toString('base64'); }
